CREATE SCHEMA IF NOT EXISTS "iris_staging";

CREATE TABLE IF NOT EXISTS iris_staging.commercial_poi_load_run (
	run_id TEXT NOT NULL, 
	task_id TEXT DEFAULT 'TASK-CRE-41' NOT NULL, 
	started_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	finished_at TIMESTAMP WITH TIME ZONE, 
	pipeline_version TEXT, 
	stage TEXT NOT NULL, 
	locations_processed INTEGER, 
	rows_inserted INTEGER, 
	rows_updated INTEGER, 
	rows_unchanged INTEGER, 
	rows_failed INTEGER, 
	duplicates_prevented INTEGER, 
	stats JSONB, 
	id_seq BIGINT, 
	PRIMARY KEY (run_id)
);

CREATE TABLE IF NOT EXISTS iris_staging.commercial_poi_raw_staging (
	observation_id TEXT NOT NULL, 
	source_uid TEXT NOT NULL, 
	operator TEXT NOT NULL, 
	source_system TEXT NOT NULL, 
	source_record_id TEXT NOT NULL, 
	source_url TEXT NOT NULL, 
	retrieved_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	payload JSONB NOT NULL, 
	html_sha256 TEXT, 
	is_duplicate BOOLEAN DEFAULT false NOT NULL, 
	duplicate_of_source_uid TEXT, 
	collection_run_id TEXT NOT NULL, 
	loaded_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (observation_id)
);

CREATE TABLE IF NOT EXISTS iris_staging.commercial_poi_staging (
	poi_uid TEXT NOT NULL, 
	source_uid TEXT NOT NULL, 
	dedup_key TEXT NOT NULL, 
	operator TEXT NOT NULL, 
	operator_slug TEXT NOT NULL, 
	location_name TEXT, 
	location_name_raw TEXT, 
	street TEXT, 
	house_number TEXT, 
	postal_code VARCHAR(5), 
	city TEXT, 
	country VARCHAR(2) DEFAULT 'DE' NOT NULL, 
	address_raw TEXT, 
	address_normalized TEXT, 
	phone TEXT, 
	email TEXT, 
	opening_hours_raw TEXT, 
	max_vehicle_height_m NUMERIC(4, 2), 
	max_vehicle_width_m NUMERIC(4, 2), 
	source_attributes JSONB, 
	source_system TEXT NOT NULL, 
	source_record_id TEXT NOT NULL, 
	source_url TEXT NOT NULL, 
	retrieved_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	source_html_sha256 TEXT, 
	geocode_provider TEXT, 
	geocode_status TEXT DEFAULT 'not_attempted' NOT NULL, 
	geocode_strategy TEXT, 
	geocode_query TEXT, 
	geocode_lat FLOAT, 
	geocode_lon FLOAT, 
	geocode_srid INTEGER, 
	geocode_display_name TEXT, 
	geocode_match_type TEXT, 
	geocode_osm_type TEXT, 
	geocode_osm_id TEXT, 
	geocode_place_rank INTEGER, 
	geocode_precision TEXT, 
	geocode_importance FLOAT, 
	geocode_result_count INTEGER, 
	geocode_ambiguous BOOLEAN, 
	geocode_ambiguity_spread_m FLOAT, 
	geocode_postcode_match BOOLEAN, 
	geocode_city_match BOOLEAN, 
	geocode_name_operator_match BOOLEAN, 
	geocode_returned_postcode TEXT, 
	geocode_returned_city TEXT, 
	geocoded_at TIMESTAMP WITH TIME ZONE, 
	geom geometry(POINT,25832), 
	x_25832 FLOAT, 
	y_25832 FLOAT, 
	building_source TEXT, 
	building_source_url TEXT, 
	building_feature_id TEXT, 
	building_geometry_type TEXT, 
	building_match_method TEXT, 
	building_geometric_match_confidence TEXT DEFAULT 'none', 
	building_distance_m FLOAT, 
	building_footprint_area_sqm NUMERIC(14, 1), 
	building_operator_attribution_status TEXT DEFAULT 'no_match' NOT NULL, 
	building_operator_attribution_evidence TEXT, 
	building_operator_attributable_area_sqm NUMERIC(14, 1), 
	building_geometry_validity TEXT, 
	building_tags JSONB, 
	building_geom geometry(MULTIPOLYGON,25832), 
	parking_source TEXT, 
	parking_source_url TEXT, 
	parking_feature_id TEXT, 
	parking_match_method TEXT, 
	parking_geometric_match_confidence TEXT DEFAULT 'none', 
	parking_distance_m FLOAT, 
	parking_area_sqm NUMERIC(14, 1), 
	parking_operator_attribution_status TEXT DEFAULT 'no_match' NOT NULL, 
	parking_operator_attribution_evidence TEXT, 
	parking_operator_attributable_area_sqm NUMERIC(14, 1), 
	parking_tags JSONB, 
	parking_geometry_validity TEXT, 
	parking_geom geometry(MULTIPOLYGON,25832), 
	parking_features_within_radius INTEGER, 
	parking_area_total_sqm NUMERIC(14, 1), 
	parking_ownership_verified BOOLEAN DEFAULT false NOT NULL, 
	operator_usable_area_verified BOOLEAN DEFAULT false NOT NULL, 
	osm_operator_tag_match BOOLEAN DEFAULT false, 
	osm_car_wash_feature_id TEXT, 
	enrichment_status TEXT DEFAULT 'not_attempted' NOT NULL, 
	geometry_provenance JSONB, 
	data_quality_flags JSONB, 
	notes TEXT, 
	row_hash TEXT NOT NULL, 
	collection_run_id TEXT, 
	load_run_id TEXT, 
	first_seen_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	last_seen_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (poi_uid), 
	CONSTRAINT uq_commercial_poi_staging_source_uid UNIQUE (source_uid), 
	CONSTRAINT uq_commercial_poi_staging_dedup_key UNIQUE (dedup_key), 
	CONSTRAINT ck_poi_postal_code_format CHECK (postal_code IS NULL OR postal_code ~ '^[0-9]{5}$'), 
	CONSTRAINT ck_poi_country_de CHECK (country = 'DE'), 
	CONSTRAINT ck_poi_geocode_status CHECK (geocode_status IN ('ok', 'ambiguous_resolved', 'not_found', 'invalid_coordinates', 'error', 'not_attempted')), 
	CONSTRAINT ck_poi_enrichment_status CHECK (enrichment_status IN ('enriched', 'partial', 'point_only', 'failed', 'not_attempted')), 
	CONSTRAINT ck_poi_building_confidence CHECK (building_geometric_match_confidence IN ('high', 'medium', 'low', 'none')), 
	CONSTRAINT ck_poi_parking_confidence CHECK (parking_geometric_match_confidence IN ('high', 'medium', 'low', 'none')), 
	CONSTRAINT ck_poi_building_attribution_status CHECK (building_operator_attribution_status IN ('operator_tagged', 'car_wash_tagged', 'third_party_named', 'unverified', 'no_match')), 
	CONSTRAINT ck_poi_parking_attribution_status CHECK (parking_operator_attribution_status IN ('operator_tagged', 'car_wash_tagged', 'third_party_named', 'unverified', 'no_match')), 
	CONSTRAINT ck_poi_building_attributable_area_requires_attribution CHECK (building_operator_attributable_area_sqm IS NULL OR building_operator_attribution_status = 'operator_tagged'), 
	CONSTRAINT ck_poi_parking_attributable_area_requires_attribution CHECK (parking_operator_attributable_area_sqm IS NULL OR parking_operator_attribution_status = 'operator_tagged'), 
	CONSTRAINT ck_poi_operator_usable_area_unverified CHECK (operator_usable_area_verified = false), 
	CONSTRAINT ck_poi_geom_srid_25832 CHECK (geom IS NULL OR ST_SRID(geom) = 25832), 
	CONSTRAINT ck_poi_geom_not_empty CHECK (geom IS NULL OR NOT ST_IsEmpty(geom)), 
	CONSTRAINT ck_poi_building_geom_srid_25832 CHECK (building_geom IS NULL OR ST_SRID(building_geom) = 25832), 
	CONSTRAINT ck_poi_building_geom_valid CHECK (building_geom IS NULL OR (NOT ST_IsEmpty(building_geom) AND ST_IsValid(building_geom))), 
	CONSTRAINT ck_poi_parking_geom_srid_25832 CHECK (parking_geom IS NULL OR ST_SRID(parking_geom) = 25832), 
	CONSTRAINT ck_poi_parking_geom_valid CHECK (parking_geom IS NULL OR (NOT ST_IsEmpty(parking_geom) AND ST_IsValid(parking_geom))), 
	CONSTRAINT ck_poi_building_area_non_negative CHECK (building_footprint_area_sqm IS NULL OR building_footprint_area_sqm >= 0), 
	CONSTRAINT ck_poi_parking_area_non_negative CHECK (parking_area_sqm IS NULL OR parking_area_sqm >= 0), 
	CONSTRAINT ck_poi_building_area_requires_geometry CHECK ((building_geom IS NULL) = (building_footprint_area_sqm IS NULL)), 
	CONSTRAINT ck_poi_geocode_precision CHECK (geocode_precision IS NULL OR geocode_precision IN ('address', 'street', 'locality', 'unknown')), 
	CONSTRAINT ck_poi_lat_range CHECK (geocode_lat IS NULL OR (geocode_lat BETWEEN -90 AND 90)), 
	CONSTRAINT ck_poi_lon_range CHECK (geocode_lon IS NULL OR (geocode_lon BETWEEN -180 AND 180))
);

CREATE INDEX IF NOT EXISTS ix_commercial_poi_staging_building_geom ON iris_staging.commercial_poi_staging USING gist (building_geom);

CREATE INDEX IF NOT EXISTS ix_commercial_poi_staging_geocode_status ON iris_staging.commercial_poi_staging (geocode_status);

CREATE INDEX IF NOT EXISTS ix_commercial_poi_staging_geom ON iris_staging.commercial_poi_staging USING gist (geom);

CREATE INDEX IF NOT EXISTS ix_commercial_poi_staging_operator ON iris_staging.commercial_poi_staging (operator_slug);

CREATE INDEX IF NOT EXISTS ix_commercial_poi_staging_parking_geom ON iris_staging.commercial_poi_staging USING gist (parking_geom);

CREATE INDEX IF NOT EXISTS ix_commercial_poi_staging_postal_code ON iris_staging.commercial_poi_staging (postal_code);
